('passage_reconstruction', '{"passage": "The Patels decided to repaint their house before winter. They chose a soft blue color after looking at many samples. A sudden rainstorm delayed the painters by two days. Despite the delay, the house was finished just before the first snow."}'::jsonb, '{"key_points": ["the Patels decided to repaint before winter", "they chose a blue color", "a rainstorm delayed the painters", "the house was finished before the first snow"]}'::jsonb, 42, 0.55, 'B2', 'approved', 'exam', 'home', 'a5000000-0000-4000-8000-000000000016', 2);
